<script setup lang="ts">
import {ref,onMounted} from 'vue';import {useRoute} from 'vue-router';import {api,allPages,download,fmtDate} from '../services/api';import {usePage} from '../services/usePage';import Notice from '../components/Notice.vue';import PrivateImage from '../components/PrivateImage.vue';import EmptyState from '../components/EmptyState.vue';import StatusBadge from '../components/StatusBadge.vue';import {Upload,LockKeyhole,Download,Shuffle,ArrowLeft,Search} from 'lucide-vue-next'
const id=String(useRoute().params.id),dataset=ref<any>(null),images=ref<any[]>([]),versions=ref<any[]>([]),files=ref<File[]>([]),state=ref(''),search=ref(''),next=ref<string|null>(null),count=ref(0),fruit=ref(''),ratios=ref('70,20,10'),seed=ref(42),duplicates=ref<any[]>([]),progress=ref(0);const {error,success,busy,act}=usePage()
async function fetchImages(url?:string,append=false){const {data}=await api.get(url||`images/?dataset=${id}&state=${state.value}&search=${encodeURIComponent(search.value)}`);images.value=append?[...images.value,...data.results]:data.results;next.value=data.next;count.value=data.count}
async function refresh(){dataset.value=(await api.get(`datasets/${id}/`)).data;await fetchImages();versions.value=await allPages(`versions/?dataset=${id}`)}onMounted(()=>act(refresh))
const upload=()=>act(async()=>{const form=new FormData();files.value.forEach(f=>form.append('files',f));form.append('fruit_code',fruit.value);const {data}=await api.post(`datasets/${id}/import/`,form,{onUploadProgress:e=>{progress.value=Math.round((e.progress||0)*100)}});await refresh();files.value=[];success.value=`Importadas: ${data.created.length}. Duplicadas omitidas: ${data.duplicates.length}. Revisa las etiquetas y los códigos de fruto.`})
const split=()=>act(async()=>{await api.post(`datasets/${id}/split/`,{ratios:ratios.value.split(',').map(x=>Number(x)/100),seed:seed.value});await refresh()},'Particiones actualizadas por grupo de fruto.')
const freeze=()=>act(async()=>{await api.post(`datasets/${id}/freeze/`,{seed:seed.value});await refresh()},'Versión congelada con originales y etiquetas revisadas.')
const similar=()=>act(async()=>{duplicates.value=(await api.get(`datasets/${id}/duplicates/`)).data.pairs;if(!duplicates.value.length)success.value='No se encontraron pares similares en la revisión.'})
const picked=(e:Event)=>{files.value=Array.from((e.target as HTMLInputElement).files||[])}
</script>
<template><RouterLink to="/datasets" class="mb-4 inline-flex items-center gap-1 text-xs text-slate-500"><ArrowLeft :size="14"/>Mis datasets</RouterLink><div class="mb-6"><h1 class="heading">{{dataset?.name||'Explorador del dataset'}}</h1><p class="subheading">{{dataset?.description}} · {{count}} imágenes</p></div><Notice :error="error" :success="success"/>
<div class="mb-6 grid gap-5 xl:grid-cols-2"><form @submit.prevent="upload" class="card"><h2 class="mb-2 flex items-center gap-2 font-semibold"><Upload :size="18"/>Importar tu dataset</h2><p class="mb-4 text-xs leading-5 text-slate-500">JPG, PNG, WEBP o ZIP YOLO con carpetas images/ y labels/. Máximo 100 MB por carga. Las etiquetas importadas quedan pendientes de revisión.</p><input class="input mb-3" type="file" multiple accept=".zip,.jpg,.jpeg,.png,.webp" @change="picked"/><label class="label">Código de fruto / grupo (opcional)</label><input v-model="fruit" class="input mb-3" placeholder="Solo si toda esta carga pertenece al mismo fruto/grupo"/><button class="btn" :disabled="busy||!files.length">{{busy?'Procesando…':'Importar '+files.length+' archivo(s)'}}</button><span v-if="busy&&progress" class="ml-3 text-xs text-slate-400">Carga {{progress}}%</span></form>
<section class="card"><h2 class="mb-2 flex items-center gap-2 font-semibold"><LockKeyhole :size="18"/>Preparar una versión</h2><p class="mb-4 text-xs leading-5 text-slate-500">Conserva las particiones importadas o redistribuye por fruto. Antes de congelar: revisa imágenes, etiquetas y códigos de grupo.</p><div class="mb-3 grid grid-cols-2 gap-3"><div><label class="label">Train, val, test (%)</label><input v-model="ratios" class="input"/></div><div><label class="label">Semilla</label><input v-model.number="seed" type="number" min="0" class="input"/></div></div><div class="flex flex-wrap gap-2"><button @click="split" :disabled="busy" class="btn-secondary"><Shuffle :size="15"/>Distribuir</button><button @click="freeze" :disabled="busy" class="btn">Congelar versión</button><button @click="similar" :disabled="busy" class="btn-secondary">Buscar similares</button></div></section></div>
<section v-if="duplicates.length" class="card mb-6"><h3 class="font-semibold">Pares similares · revisa antes de particionar</h3><p class="mb-3 text-xs text-slate-500">La similitud visual es una sugerencia, no una confirmación de duplicado.</p><p v-for="pair in duplicates" :key="pair.first+pair.second" class="py-1 text-xs"><RouterLink :to="'/images/'+pair.first" class="text-emerald-700 underline">{{pair.first_name}}</RouterLink> ↔ <RouterLink :to="'/images/'+pair.second" class="text-emerald-700 underline">{{pair.second_name}}</RouterLink></p></section>
<form class="mb-5 flex flex-wrap gap-3" @submit.prevent="act(()=>fetchImages())"><input v-model="search" class="input max-w-xs" placeholder="Buscar imagen…"/><select v-model="state" class="input max-w-56" @change="act(()=>fetchImages())"><option value="">Todos los estados</option><option value="pending">Pendientes</option><option value="healthy">Sin lesiones anotadas</option><option value="lesion">Con roña</option><option value="discarded">Descartadas</option></select><button class="btn-secondary">Buscar</button></form>
<div class="grid grid-cols-2 gap-4 md:grid-cols-3 xl:grid-cols-4"><RouterLink v-for="img in images" :key="img.id" :to="'/images/'+img.id" class="overflow-hidden rounded-2xl border border-slate-200 bg-white transition hover:border-emerald-400"><PrivateImage :src="`images/${img.id}/file/`" :alt="img.name" class="aspect-square w-full object-contain bg-[#edf0e9]"/><div class="p-3"><p class="truncate text-xs font-semibold">{{img.name}}</p><div class="my-2"><StatusBadge :value="img.state"/></div><p class="text-[10px] text-slate-400">{{img.width}} × {{img.height}} · {{img.split||'Sin partición'}}</p><p class="mt-1 truncate text-[10px]" :class="img.fruit_code?'text-slate-400':'text-amber-600'">{{img.fruit_code||'Falta código de fruto/grupo'}}</p></div></RouterLink></div><EmptyState v-if="!images.length" title="Sin imágenes para mostrar" text="Importa tu dataset o ajusta los filtros."/><button v-if="next" @click="act(()=>fetchImages(next!,true))" class="btn-secondary mt-5" :disabled="busy">Cargar más</button>
<section class="card mt-7"><h2 class="mb-4 font-semibold">Versiones congeladas</h2><p v-if="!versions.length" class="text-sm text-slate-400">Las versiones aparecerán después de revisar y congelar el dataset.</p><div v-for="v in versions" :key="v.id" class="flex items-center justify-between border-t border-slate-100 py-3"><div><p class="text-sm font-semibold">Versión {{v.number}} · {{v.count}} imágenes</p><p class="mt-1 text-xs text-slate-400">{{fmtDate(v.created_at)}} · {{v.manifest_hash.slice(0,12)}}</p></div><button @click="act(()=>download(`versions/${v.id}/download/`,`dataset-v${v.number}.zip`))" class="btn-secondary"><Download :size="15"/>YOLO ZIP</button></div></section></template>
